package lower

import (
	"strings"
	"testing"
)

// tsc's sortAndDeduplicate falls back to a default comparer through `as unknown as Comparer<T>`
// (core.ts:810, the wall in front of 73 roots), a cast that's true only by the overloads: the one
// overload that lets a caller leave the comparers out takes strings. Per-overload proof erases the pair
// with no check (overload_default_cast.go; Adamic's ruling on #b5w3ycg, #25t5461). tsc's shape (core.ts:805-
// 810: an overload `(array: readonly string[])`, one taking a comparer, and the implementation's
// `equalityComparer ?? comparer ?? x as unknown as Comparer<T>`, with Comparer standing in for its
// EqualityComparer) lowers and agrees with Node, natively too; the string overload's T is inferred from
// array. The
// twins stay refused: a second overload that also lets the comparer be left out, under a generic T, and
// a default that's a number comparer under the string overload. In .a the pair keeps its refusal.
// The proof holds only while every call is resolved against the overloads (Compiler's road on 986ad82d).
// Assigning the implementation where its comparer is optional fails tsc's strictFunctionTypes today
// (Language's probes), but the proof shouldn't rest on that rule: any reference that isn't a callee keeps
// the pair refused, a plain alias and a .call among them, and so does any this parameter in the set,
// which shifts the positions the proof compares. A pair in a function with no overloads keeps its refusal (pick2; a lone hop to unknown, pick's, is an
// upcast main admits). Mutants: overloadAdmitsAbsence
// answering true for every overload, under which the tsc shape is refused (its comparer-taking overload
// is judged, at a generic T); castAssignable skipped in overloadDefaultPair, under which both twins
// lower; the overload count dropped, under which pick2's pair lowers; onlyCalled answering true, under
// which the function value and the .call lower; and the this-parameter check dropped, under which the
// this-parameter twin lowers.
func TestOverloadDefaultCastIsProvenPerOverload(t *testing.T) {
	t.Parallel()
	const want = "1,2,3\n"
	for _, source := range []struct{ name, text string }{{"tsc", "type Comparison = -1 | 0 | 1;\ntype Comparer<T> = (a: T, b: T) => Comparison;\nfunction compareStringsCaseSensitive(a: string, b: string): Comparison { return a < b ? -1 : a > b ? 1 : 0; }\nfunction compareNumbers(a: number, b: number): Comparison { return a < b ? -1 : a > b ? 1 : 0; }\nfunction sortWith<T>(array: readonly T[], comparer: Comparer<T>): T[] { return [...array].sort(comparer); }\nfunction dedupeSorted<T>(sorted: readonly T[], comparer: Comparer<T>): T[] {\n\tconst out: T[] = [];\n\tfor (const item of sorted) {\n\t\tif (!out.some(seen => comparer(seen, item) === 0)) {\n\t\t\tout.push(item);\n\t\t}\n\t}\n\treturn out;\n}\nfunction sortAndDeduplicate(array: readonly string[]): string[];\nfunction sortAndDeduplicate<T>(array: readonly T[], comparer: Comparer<T>, equalityComparer?: Comparer<T>): T[];\nfunction sortAndDeduplicate<T>(array: readonly T[], comparer?: Comparer<T>, equalityComparer?: Comparer<T>): T[] {\n\treturn dedupeSorted(sortWith(array, comparer ?? compareStringsCaseSensitive as unknown as Comparer<T>), equalityComparer ?? comparer ?? compareStringsCaseSensitive as unknown as Comparer<T>);\n}\nconsole.log(sortAndDeduplicate(['b', 'a', 'c', 'a']).join(','));\nconsole.log(sortAndDeduplicate([3, 1, 2, 1], compareNumbers).join(','));\n"}} {
		t.Run(source.name, func(t *testing.T) {
			t.Parallel()
			program := lowersAndAgreesWithNodeAs(t, source.text, ".ts")
			if code, stdout, stderr := brandedNative(t, program); code != 0 || stdout != "a,b,c\n"+want {
				t.Fatalf("native: exit %d, stdout %q, stderr %q", code, stdout, stderr)
			}
		})
	}
	for _, twin := range []struct{ name, text, where string }{{"generic", "type Comparison = -1 | 0 | 1;\ntype Comparer<T> = (a: T, b: T) => Comparison;\nfunction compareStringsCaseSensitive(a: string, b: string): Comparison { return a < b ? -1 : a > b ? 1 : 0; }\nfunction compareNumbers(a: number, b: number): Comparison { return a < b ? -1 : a > b ? 1 : 0; }\nfunction sortWith<T>(array: readonly T[], comparer: Comparer<T>): T[] { return [...array].sort(comparer); }\nfunction dedupeSorted<T>(sorted: readonly T[], comparer: Comparer<T>): T[] {\n\tconst out: T[] = [];\n\tfor (const item of sorted) {\n\t\tif (!out.some(seen => comparer(seen, item) === 0)) {\n\t\t\tout.push(item);\n\t\t}\n\t}\n\treturn out;\n}\nfunction sortAndDeduplicate(array: readonly string[]): string[];\nfunction sortAndDeduplicate<T>(array: readonly T[], comparer?: Comparer<T>, equalityComparer?: Comparer<T>): T[];\nfunction sortAndDeduplicate<T>(array: readonly T[], comparer?: Comparer<T>, equalityComparer?: Comparer<T>): T[] {\n\treturn dedupeSorted(sortWith(array, comparer ?? compareStringsCaseSensitive as unknown as Comparer<T>), equalityComparer ?? comparer ?? compareStringsCaseSensitive as unknown as Comparer<T>);\n}\nconsole.log(sortAndDeduplicate(['b', 'a', 'c', 'a']).join(','));\nconsole.log(sortAndDeduplicate([3, 1, 2, 1], compareNumbers).join(','));\n", ":18:50"}, {"function_value", "type Comparison = -1 | 0 | 1;\ntype Comparer<T> = (a: T, b: T) => Comparison;\nfunction compareStringsCaseSensitive(a: string, b: string): Comparison { return a < b ? -1 : a > b ? 1 : 0; }\nfunction compareNumbers(a: number, b: number): Comparison { return a < b ? -1 : a > b ? 1 : 0; }\nfunction sortWith<T>(array: readonly T[], comparer: Comparer<T>): T[] { return [...array].sort(comparer); }\nfunction dedupeSorted<T>(sorted: readonly T[], comparer: Comparer<T>): T[] {\n\tconst out: T[] = [];\n\tfor (const item of sorted) {\n\t\tif (!out.some(seen => comparer(seen, item) === 0)) {\n\t\t\tout.push(item);\n\t\t}\n\t}\n\treturn out;\n}\nfunction sortAndDeduplicate(array: readonly string[]): string[];\nfunction sortAndDeduplicate<T>(array: readonly T[], comparer: Comparer<T>, equalityComparer?: Comparer<T>): T[];\nfunction sortAndDeduplicate<T>(array: readonly T[], comparer?: Comparer<T>, equalityComparer?: Comparer<T>): T[] {\n\treturn dedupeSorted(sortWith(array, comparer ?? compareStringsCaseSensitive as unknown as Comparer<T>), equalityComparer ?? comparer ?? compareStringsCaseSensitive as unknown as Comparer<T>);\n}\nconsole.log(sortAndDeduplicate(['b', 'a', 'c', 'a']).join(','));\nconsole.log(sortAndDeduplicate([3, 1, 2, 1], compareNumbers).join(','));\nconst alias = sortAndDeduplicate;\nconsole.log(alias(['b', 'a']).join(','));\n", ":18:50"}, {"call", "type Comparison = -1 | 0 | 1;\ntype Comparer<T> = (a: T, b: T) => Comparison;\nfunction compareStringsCaseSensitive(a: string, b: string): Comparison { return a < b ? -1 : a > b ? 1 : 0; }\nfunction compareNumbers(a: number, b: number): Comparison { return a < b ? -1 : a > b ? 1 : 0; }\nfunction sortWith<T>(array: readonly T[], comparer: Comparer<T>): T[] { return [...array].sort(comparer); }\nfunction dedupeSorted<T>(sorted: readonly T[], comparer: Comparer<T>): T[] {\n\tconst out: T[] = [];\n\tfor (const item of sorted) {\n\t\tif (!out.some(seen => comparer(seen, item) === 0)) {\n\t\t\tout.push(item);\n\t\t}\n\t}\n\treturn out;\n}\nfunction sortAndDeduplicate(array: readonly string[]): string[];\nfunction sortAndDeduplicate<T>(array: readonly T[], comparer: Comparer<T>, equalityComparer?: Comparer<T>): T[];\nfunction sortAndDeduplicate<T>(array: readonly T[], comparer?: Comparer<T>, equalityComparer?: Comparer<T>): T[] {\n\treturn dedupeSorted(sortWith(array, comparer ?? compareStringsCaseSensitive as unknown as Comparer<T>), equalityComparer ?? comparer ?? compareStringsCaseSensitive as unknown as Comparer<T>);\n}\nconsole.log(sortAndDeduplicate(['b', 'a', 'c', 'a']).join(','));\nconsole.log(sortAndDeduplicate([3, 1, 2, 1], compareNumbers).join(','));\nconsole.log(sortAndDeduplicate.call(null, [3, 1, 2], compareNumbers).join(','));\n", ":18:50"}, {"this_parameter", "type Comparison = -1 | 0 | 1;\ntype Comparer<T> = (a: T, b: T) => Comparison;\nfunction compareStringsCaseSensitive(a: string, b: string): Comparison { return a < b ? -1 : a > b ? 1 : 0; }\nfunction compareNumbers(a: number, b: number): Comparison { return a < b ? -1 : a > b ? 1 : 0; }\nfunction sortWith<T>(array: readonly T[], comparer: Comparer<T>): T[] { return [...array].sort(comparer); }\nfunction dedupeSorted<T>(sorted: readonly T[], comparer: Comparer<T>): T[] {\n\tconst out: T[] = [];\n\tfor (const item of sorted) {\n\t\tif (!out.some(seen => comparer(seen, item) === 0)) {\n\t\t\tout.push(item);\n\t\t}\n\t}\n\treturn out;\n}\nfunction sortAndDeduplicate(this: void, array: readonly string[]): string[];\nfunction sortAndDeduplicate<T>(this: void, array: readonly T[], comparer: Comparer<T>, equalityComparer?: Comparer<T>): T[];\nfunction sortAndDeduplicate<T>(this: void, array: readonly T[], comparer?: Comparer<T>, equalityComparer?: Comparer<T>): T[] {\n\treturn dedupeSorted(sortWith(array, comparer ?? compareStringsCaseSensitive as unknown as Comparer<T>), equalityComparer ?? comparer ?? compareStringsCaseSensitive as unknown as Comparer<T>);\n}\nconsole.log(sortAndDeduplicate(['b', 'a', 'c', 'a']).join(','));\nconsole.log(sortAndDeduplicate([3, 1, 2, 1], compareNumbers).join(','));\n", ":18:50"}, {"number", "type Comparison = -1 | 0 | 1;\ntype Comparer<T> = (a: T, b: T) => Comparison;\nfunction compareStringsCaseSensitive(a: string, b: string): Comparison { return a < b ? -1 : a > b ? 1 : 0; }\nfunction compareNumbers(a: number, b: number): Comparison { return a < b ? -1 : a > b ? 1 : 0; }\nfunction sortWith<T>(array: readonly T[], comparer: Comparer<T>): T[] { return [...array].sort(comparer); }\nfunction dedupeSorted<T>(sorted: readonly T[], comparer: Comparer<T>): T[] {\n\tconst out: T[] = [];\n\tfor (const item of sorted) {\n\t\tif (!out.some(seen => comparer(seen, item) === 0)) {\n\t\t\tout.push(item);\n\t\t}\n\t}\n\treturn out;\n}\nfunction sortAndDeduplicate(array: readonly string[]): string[];\nfunction sortAndDeduplicate<T>(array: readonly T[], comparer: Comparer<T>, equalityComparer?: Comparer<T>): T[];\nfunction sortAndDeduplicate<T>(array: readonly T[], comparer?: Comparer<T>, equalityComparer?: Comparer<T>): T[] {\n\treturn dedupeSorted(sortWith(array, comparer ?? compareNumbers as unknown as Comparer<T>), equalityComparer ?? comparer ?? compareNumbers as unknown as Comparer<T>);\n}\nconsole.log(sortAndDeduplicate([3, 1, 2, 1], compareNumbers).join(','));\n", ":18:50"}} {
		t.Run(twin.name, func(t *testing.T) {
			t.Parallel()
			_, err := lowerSourceAs(t, twin.text, ".ts")
			if err == nil || !strings.Contains(err.Error(), twin.where+": Adamic 0.1 refuses a cast the runtime can't check") {
				t.Fatalf("want the cast refused at %s, got %v", twin.where, err)
			}
		})
	}
	t.Run("a", func(t *testing.T) {
		t.Parallel()
		_, err := lowerSourceAs(t, "type Comparison = -1 | 0 | 1;\ntype Comparer<T> = (a: T, b: T) => Comparison;\nfunction compareStringsCaseSensitive(a: string, b: string): Comparison { return a < b ? -1 : a > b ? 1 : 0; }\nfunction compareNumbers(a: number, b: number): Comparison { return a < b ? -1 : a > b ? 1 : 0; }\nfunction sortWith<T>(array: readonly T[], comparer: Comparer<T>): T[] { return [...array].sort(comparer); }\nfunction dedupeSorted<T>(sorted: readonly T[], comparer: Comparer<T>): T[] {\n\tconst out: T[] = [];\n\tfor (const item of sorted) {\n\t\tif (!out.some(seen => comparer(seen, item) === 0)) {\n\t\t\tout.push(item);\n\t\t}\n\t}\n\treturn out;\n}\nfunction sortAndDeduplicate(array: readonly string[]): string[];\nfunction sortAndDeduplicate<T>(array: readonly T[], comparer: Comparer<T>, equalityComparer?: Comparer<T>): T[];\nfunction sortAndDeduplicate<T>(array: readonly T[], comparer?: Comparer<T>, equalityComparer?: Comparer<T>): T[] {\n\treturn dedupeSorted(sortWith(array, comparer ?? compareStringsCaseSensitive as unknown as Comparer<T>), equalityComparer ?? comparer ?? compareStringsCaseSensitive as unknown as Comparer<T>);\n}\nconsole.log(sortAndDeduplicate(['b', 'a', 'c', 'a']).join(','));\nconsole.log(sortAndDeduplicate([3, 1, 2, 1], compareNumbers).join(','));\n", ".a")
		if err == nil {
			t.Fatal("want the pair refused in .a, got it lowered")
		}
		t.Logf("a: %v", err)
	})
	t.Run("no_overloads", func(t *testing.T) {
		t.Parallel()
		_, err := lowerSourceAs(t, "type Comparison = -1 | 0 | 1;\ntype Comparer<T> = (a: T, b: T) => Comparison;\nfunction compareStringsCaseSensitive(a: string, b: string): Comparison { return a < b ? -1 : a > b ? 1 : 0; }\nfunction compareNumbers(a: number, b: number): Comparison { return a < b ? -1 : a > b ? 1 : 0; }\nfunction sortWith<T>(array: readonly T[], comparer: Comparer<T>): T[] { return [...array].sort(comparer); }\nfunction dedupeSorted<T>(sorted: readonly T[], comparer: Comparer<T>): T[] {\n\tconst out: T[] = [];\n\tfor (const item of sorted) {\n\t\tif (!out.some(seen => comparer(seen, item) === 0)) {\n\t\t\tout.push(item);\n\t\t}\n\t}\n\treturn out;\n}\nfunction pick<T>(comparer?: Comparer<T>): unknown {\n\treturn comparer ?? compareStringsCaseSensitive as unknown;\n}\nfunction pick2(comparer?: Comparer<string>): Comparer<string> {\n\treturn comparer ?? compareStringsCaseSensitive as unknown as Comparer<string>;\n}\nconsole.log(String(pick() === compareStringsCaseSensitive));\nconsole.log(String(pick2()('a', 'b')));\n", ".ts")
		if err == nil || !strings.Contains(err.Error(), ":19:21: Adamic 0.1 refuses a cast the runtime can't check") {
			t.Fatalf("want pick2's pair refused at :19:21, got %v", err)
		}
	})
}
